import * as React from "react";
import { cx } from "./cx";

export interface SpinnerProps extends React.HTMLAttributes<HTMLSpanElement> {
  label?: string;
}

/** Hairline ring. Stops under prefers-reduced-motion. */
export function Spinner({ label = "Loading", className, ...props }: SpinnerProps) {
  return <span role="status" aria-label={label} className={cx("rs-spinner", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Spinner: a hairline ring. Motion stops under reduced-motion ── */
.rs-spinner{display:inline-block;width:16px;height:16px;border:1.5px solid var(--divider);border-top-color:var(--text);border-radius:0;animation:rs-spin .7s linear infinite;vertical-align:middle}
@keyframes rs-spin{to{transform:rotate(360deg)}}
